command exit=0: set -euxo pipefail
export DEBIAN_FRONTEND=noninteractive
if ! command -v nginx >/dev/null 2>&1; then
  if command -v apt-get >/dev/null 2>&1; then
    apt-get update
    apt-get install -y nginx
  else
    echo 'BLOCKER: no nginx binary and no supported package manager found' >&2
    exit 1
  fi
fi

mkdir -p /etc/nginx/conf.d /var/www/html /var/log/nginx

python3 - <<'PY'
from pathlib import Path
import re
conf = Path('/etc/nginx/nginx.conf')
text = conf.read_text()
if 'log_format benchmark' not in text or 'limit_req_zone $binary_remote_addr zone=benchmark_zone:10m rate=10r/s;' not in text:
    lines = text.splitlines()
    out = []
    in_http = False
    inserted = False
    include_present = False
    brace_level = 0
    for i, line in enumerate(lines):
        stripped = line.strip()
        if not in_http and re.match(r'^\s*http\s*\{\s*$', line):
            out.append(line)
            out.append('    log_format benchmark \'$time_local $request_method $status "$http_user_agent"\';')
            out.append('    limit_req_zone $binary_remote_addr zone=benchmark_zone:10m rate=10r/s;')
            in_http = True
            inserted = True
            brace_level = 1
            continue
        if in_http:
            if 'include /etc/nginx/conf.d/*.conf;' in stripped:
                include_present = True
            if stripped == '}':
                if not include_present:
                    out.append('    include /etc/nginx/conf.d/*.conf;')
                    include_present = True
                out.append(line)
                in_http = False
                continue
        out.append(line)
    if not inserted:
        raise SystemExit('Could not locate http block in nginx.conf')
    conf.write_text('\n'.join(out) + ('\n' if text.endswith('\n') else ''))

site = Path('/etc/nginx/conf.d/benchmark-site.conf')
site.write_text('''server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;
    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    location / {
        limit_req zone=benchmark_zone burst=10;
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
''')

Path('/var/www/html/index.html').write_text('Welcome to the benchmark webserver\n')
Path('/var/www/html/404.html').write_text('Page not found - Please check your URL\n')
PY

rm -f /etc/nginx/sites-enabled/default || true

nginx -t -c /etc/nginx/nginx.conf
(nginx -s quit -c /etc/nginx/nginx.conf || true)
sleep 1
nginx -c /etc/nginx/nginx.conf
sleep 1

printf '\n== localhost root ==\n'
curl -si --max-time 5 http://127.0.0.1:8080/
printf '\n== localhost missing ==\n'
curl -si --max-time 5 http://127.0.0.1:8080/no-such-page
printf '\n== default site state ==\n'
if [ -e /etc/nginx/sites-enabled/default ]; then echo 'default site still present'; else echo 'default site absent'; fi
printf '\n== access log location ==\n%s\n' '/var/log/nginx/benchmark-access.log'

